package com.example.starter.firmware.domain;

/**
 * 设备投放任务，同设备同发布单最多一条。
 *
 * @param id             任务ID
 * @param releaseId      所属发布单ID
 * @param deviceId       设备ID
 * @param status         任务状态
 * @param firstResult    首次回执结果（SUCCESS/FAILED），未回执为 null
 * @param profileVersion 创建任务时冻结的设备画像版本号（从1开始）；未启用画像门禁的任务为 null
 */
public record RolloutTask(long id, long releaseId, String deviceId, TaskStatus status,
                          ReceiptResult firstResult, Integer profileVersion) {
}

package com.example.starter.firmware.domain;

import java.util.List;

/**
 * 固件版本硬件兼容要求：版本声明允许型号集合、最低内存与必需能力标签。
 * 要求一经声明只增不改，重复声明同一版本冲突。
 *
 * @param id              硬件要求ID
 * @param firmwareVersion 固件目标版本号
 * @param minMemoryMb     最低运行内存，单位MB（1GB=1024MB）；null 表示不限制内存
 * @param models          允许投放的设备型号集合，画像型号须命中其一
 * @param tags            必需能力标签集合，画像须包含全部；空集合表示不要求标签
 */
public record HardwareRequirement(long id, String firmwareVersion, Integer minMemoryMb,
                                  List<String> models, List<String> tags) {
}

package com.example.starter.firmware.domain;

import java.util.List;

/**
 * 设备硬件画像的一个不可变版本快照。画像更新只追加新版本，历史版本不可改，
 * 已下发任务持续引用其创建时冻结的版本。
 *
 * @param id        画像版本记录ID
 * @param deviceId  设备ID
 * @param version   画像版本号，从1开始，只增不改
 * @param model     画像登记型号；null 表示该版本画像缺少型号字段，门禁按不兼容处理
 * @param memoryMb  画像登记运行内存，单位MB；null 表示缺少内存字段，门禁按不兼容处理
 * @param tags      该版本具备的能力标签，按字典序保存
 */
public record ProfileSnapshot(long id, String deviceId, int version, String model, Integer memoryMb,
                              List<String> tags) {
}

package com.example.starter.firmware.domain;

/**
 * 硬件不兼容排除原因码。除 PROFILE_MISSING 外均表示画像存在但不满足对应门禁条件。
 */
public enum ExclusionReason {

    /** 设备从未提交过硬件画像。 */
    PROFILE_MISSING,
    /** 画像缺少型号字段。 */
    MODEL_MISSING,
    /** 画像缺少内存字段。 */
    MEMORY_MISSING,
    /** 画像型号不在版本声明的型号集合内。 */
    MODEL_NOT_REQUIRED,
    /** 画像内存低于版本声明的最低内存。 */
    MEMORY_INSUFFICIENT,
    /** 画像缺少版本声明的全部或部分必需能力标签。 */
    REQUIRED_TAG_MISSING
}

package com.example.starter.firmware.domain;

/**
 * 发布单维度的硬件不兼容排除记录。被排除设备不创建任务、不计入失败率；
 * 设备在后续投放中转为兼容并创建任务后，对应记录移除。
 *
 * @param id             排除记录ID
 * @param releaseId      所属发布单ID
 * @param deviceId       被排除设备ID
 * @param reason         排除原因码
 * @param profileVersion 判定时使用的设备画像版本；设备无画像时为 null
 */
public record RolloutExclusion(long id, long releaseId, String deviceId, ExclusionReason reason,
                               Integer profileVersion) {
}

package com.example.starter.firmware.domain;

/**
 * 单次硬件画像兼容门禁判定结果，基于设备当次冻结画像与版本声明要求计算。
 *
 * @param compatible     是否兼容（型号命中、内存达标且包含全部必需标签）
 * @param reason         不兼容原因；兼容时为 null
 * @param profile        判定所用画像版本；设备无画像时为 null
 */
public record GateDecision(boolean compatible, ExclusionReason reason, ProfileSnapshot profile) {

    public static GateDecision pass(ProfileSnapshot profile) {
        return new GateDecision(true, null, profile);
    }

    public static GateDecision reject(ExclusionReason reason, ProfileSnapshot profile) {
        return new GateDecision(false, reason, profile);
    }
}

