}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.HardwareRequirement;

import java.util.List;

/**
 * 固件版本硬件兼容要求视图。
 */
public record HardwareRequirementView(String firmwareVersion, Integer minMemoryMb,
                                      List<String> models, List<String> tags) {

    public static HardwareRequirementView of(HardwareRequirement requirement) {
        return new HardwareRequirementView(requirement.firmwareVersion(), requirement.minMemoryMb(),
                requirement.models(), requirement.tags());
    }
}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.ProfileSnapshot;

import java.util.List;

/**
 * 设备硬件画像当前版本视图。
 */
public record ProfileView(String deviceId, int version, String model, Integer memoryMb, List<String> tags) {

    public static ProfileView of(ProfileSnapshot profile) {
        return new ProfileView(profile.deviceId(), profile.version(), profile.model(),
                profile.memoryMb(), profile.tags());
    }
}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.RolloutExclusion;

/**
 * 硬件不兼容排除视图，供发布人审计：携带排除原因与判定时使用的画像版本。
 */
public record ExclusionView(String deviceId, String reasonCode, Integer profileVersion) {

    public static ExclusionView of(RolloutExclusion exclusion) {
        return new ExclusionView(exclusion.deviceId(), exclusion.reason().name(),
                exclusion.profileVersion());
    }
}

package com.example.starter.firmware.api;

import java.util.List;

/**
 * 发布单硬件不兼容排除清单响应（只读，发布人视角）。
 */
public record ExclusionListResponse(List<ExclusionView> exclusions) {
}

package com.example.starter.firmware.api;

import java.util.List;

/**
 * 发布人批量投放筛选结果：created 为当次通过兼容门禁并创建（或已存在）的任务，
 * excluded 为不兼容设备及原因。不兼容设备不创建任务，也不计入失败率。
 */
public record DispatchResponse(long releaseId, List<TaskView> created, List<ExclusionView> excluded) {
}

